-- Generated by `engine types sync` from types/*.toml.
-- create type `update`

CREATE TABLE content_update (
    id bigserial PRIMARY KEY,
    slug text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length(slug) <= 80),
    status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published')),
    version integer NOT NULL DEFAULT 1,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    "title" text,
    "body" text
);
CREATE TRIGGER content_update_changes
    AFTER INSERT OR UPDATE OR DELETE ON content_update
    FOR EACH ROW EXECUTE FUNCTION engine_record_change('update');
